SET TimeZone = 'Asia/Kolkata';

CREATE TABLE payments (
  payment_id  integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  paid_at     timestamptz   NOT NULL,
  amount      numeric(10,2) NOT NULL
);

INSERT INTO payments (paid_at, amount) VALUES
  ('2026-11-27 09:15+05:30', 250.00),
  ('2026-11-27 09:40+05:30', 100.00),
  ('2026-11-27 11:05+05:30', 600.00),
  ('2026-11-27 12:59+05:30',  80.00);

SET TimeZone = 'UTC';

SELECT * FROM generate_series('2001-10-22 00:00 -04:00'::timestamptz,
                              '2001-10-30 00:00 -05:00'::timestamptz,
                              '1 day'::interval, 'America/New_York');

